//en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1868","k":"right","a":"civil rights","cite":"Fourteenth Amendment","dsc":"Requires states to treat people equally under the law."}},{"n":"Right Against Unreasonable Search","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"Fourth Amendment","dsc":"Protects against unreasonable searches and seizures."}},{"n":"Right to a Fair Trial","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"Sixth Amendment","dsc":"Guarantees a speedy, public trial with counsel and jury."}},{"n":"Right to Vote","c":"rights","r":"https://www.dol.gov/agencies/oasam/centers-offices/civil-rights-center/internal/statutes-regulations-2","f":{"j":"United States","y":"1870","k":"right","a":"voting rights","cite":"Fifteenth and Nineteenth Amendments","dsc":"Protects voting free of racial and sex discrimination."}},{"n":"Miranda Rights","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1966","k":"right","a":"criminal procedure","cite":"Miranda v. Arizona","dsc":"Warnings required before custodial interrogation."}},{"n":"Right to Counsel","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1963","k":"right","a":"criminal procedure","cite":"Gideon v. Wainwright","dsc":"Indigent defendants get appointed counsel in felony cases."}},{"n":"GDPR Right of Access","c":"rights","r":"https://en.wikipedia.org/wiki/GDPR_2016","f":{"j":"European Union","y":"2018","k":"right","a":"data privacy","cite":"GDPR Article 15","dsc":"Individuals may obtain confirmation and a copy of their personal data."}},{"n":"GDPR Right to Erasure","c":"rights","r":"https://en.wikipedia.org/wiki/GDPR_2016","f":{"j":"European Union","y":"2018","k":"right","a":"data privacy","cite":"GDPR Article 17","dsc":"Individuals may request deletion of personal data in defined cases."}},{"n":"GDPR Right to Data Portability","c":"rights","r":"https://en.wikipedia.org/wiki/GDPR_2016","f":{"j":"European Union","y":"2018","k":"right","a":"data privacy","cite":"GDPR Article 20","dsc":"Individuals may receive their data in a portable format."}},{"n":"Freedom of Assembly","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"First Amendment","dsc":"Protects peaceful assembly from government interference."}},{"n":"Religious Exercise Rights","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"First Amendment","dsc":"Bars government establishment of religion and protects its free exercise."}},{"n":"Right to Bear Arms","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"Second Amendment","dsc":"Protects an individual right to keep and bear arms."}},{"n":"Protection Against Self-Incrimination","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"criminal procedure","cite":"Fifth Amendment","dsc":"No person may be compelled to testify against themselves."}},{"n":"Right to Petition","c":"rights","r":"https://en.wikipedia.org/wiki/List_of_United_States_federal_legislation,_1901–2001","f":{"j":"United States","y":"1791","k":"right","a":"civil liberties","cite":"First Amendment","dsc":"Protects petitions to the government for redress of